custom_css:
/* Page background */
body {
  background: #f3f7f4;
  color: #243c30;
}

/* Green introductory panel */
.web-form-header {
  background: linear-gradient(125deg, #123e2b, #226344) !important;
  border: none !important;
  border-radius: 18px !important;
  padding: 32px !important;
  margin-bottom: 24px !important;
  box-shadow: 0 8px 24px rgba(18, 62, 43, 0.10);
}

.web-form-header .web-form-head {
  border: none !important;
  padding:8px;
}

.web-form-header h1,
.web-form-header h2,
.web-form-header .title {
  color: #ffffff !important;
  font-weight: 700;
  letter-spacing: -0.025em;
}

.web-form-header p,
.web-form-header .web-form-introduction,
.web-form-header .text-muted {
  color: #e0eee5 !important;
  line-height: 1.7;
}
s
.web-form-header a {
  color: #ffffff;
  text-decoration: underline;
}

/* Main form card */
.web-form {
  background: #ffffff !important;
  border: 1px solid #dce8df !important;
  border-radius: 18px !important;
  padding: 30px !important;
  box-shadow: 0 10px 30px rgba(25, 65, 43, 0.05);
}

/* Section headings */
.web-form .section-head {
  color: #185438;
  font-size: 18px;
  font-weight: 700;
  padding: 12px 16px;
  margin-bottom: 20px;
  background: #edf6ef;
  border-left: 4px solid #348251;
  border-radius: 0 8px 8px 0;
}

.web-form .form-section {
  border-color: #e7eee9;
  margin-top: 20px;
  padding-top: 20px;
}

/* Labels and spacing */
.web-form .frappe-control {
  margin-bottom: 20px;
}

.web-form .control-label {
  color: #304c3c;
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 8px;
}

/* Text boxes */
.web-form .form-control {
  background-color: #fbfdfb;
  color: #243c30;
  border: 1px solid #cfddd3;
  border-radius: 9px;
  min-height: 44px;
  padding: 10px 12px;
  font-size: 16px;
  box-shadow: none;
}

.web-form textarea.form-control {
  min-height: 100px;
}

.web-form .form-control::placeholder {
  color: #748278;
}

.web-form .form-control:focus {
  background-color: #ffffff;
  border-color: #287346;
  box-shadow: 0 0 0 3px rgba(40, 115, 70, 0.14);
}

.web-form .form-control:disabled,
.web-form .form-control[readonly] {
  background-color: #eef2ef;
}

/* Helper text */
.web-form .help-box,
.web-form .text-muted {
  color: #64736a !important;
  font-size: 13px;
  line-height: 1.6;
}

/* Receipt attachment button */
.web-form .attach-button {
  background: #eff7f1 !important;
  color: #185438 !important;
  border: 1px dashed #72a584 !important;
  border-radius: 9px;
  padding: 12px 18px;
  min-height: 44px;
}

/* Checkboxes */
.web-form input[type="checkbox"] {
  accent-color: #226344;
  width: 18px;
  height: 18px;
}

/* Primary actions */
.web-form .btn-primary,
.web-form-footer .btn-primary,
.web-form-header .btn-primary {
  background: #226344 !important;
  border-color: #226344 !important;
  color: #ffffff !important;
  border-radius: 9px;
  min-height: 46px;
  padding: 12px 26px;
  font-size: 15px;
  font-weight: 600;
}

.web-form .btn-primary:hover,
.web-form-footer .btn-primary:hover {
  background: #164a31 !important;
  border-color: #164a31 !important;
}

.web-form .btn:focus-visible,
.web-form-footer .btn:focus-visible {
  outline: 3px solid #80b494;
  outline-offset: 3px;
}

.web-form-footer {
  margin-top: 24px;
}

/* Mobile layout */
@media (max-width: 767px) {
  .web-form-header {
    padding: 24px 20px !important;
    border-radius: 12px !important;
  }

  .web-form-header h1 {
    font-size: 27px;
  }

  .web-form {
    padding: 20px 16px !important;
    border-radius: 12px !important;
  }

  .web-form .section-head {
    font-size: 16px;
  }

  .web-form-footer .btn-primary {
    width: 100%;
  }
}
